        return value > 0
    elif hasattr(value, 'shape'):
        all_positive = True
        for val in value.flatten():
            if not (val >= 0):
                all_positive = False
                break
        return all_positive
    else:
        raise TypeError("Unsupported input type")
if __name__ == '__main__':
    sample_scalar = -5.0
    sample_array = np.array([1, 2, 3])
    sample_series_data = [4, 5]
    print(check_positivity(sample_scalar))
    print(check_positivity(np.array([-1, -2])))
    print(check_positivity(sample_array))

import numpy as np
from typing import Union
def is_positive(value: Union[int, float, np.ndarray]) -> bool:
    if isinstance(value, (int, float)):
        return value > 0
    elif hasattr(value, '__iter__') and not isinstance(value, str):
        try:
            arr = np.asarray(value)
            return np.all(arr > 0)
        except Exception:
            raise TypeError("Input must be a numeric scalar or array-like.")
    else:
        raise TypeError(f"Unsupported type {type(value).__name__}.")
if __name__ == '__main__':
    test_cases = [5, -3.2, 0, np.array([1, 2]), np.array([-1, 2])]
    for case in test_cases:
        print(f"Input: {case}, Is Positive: {is_positive(case)}")

import cmath
def is_integer(value):
    return isinstance(value, int) and not isinstance(value, bool)
def is_float(value):
    return isinstance(value, float) and not isinstance(value, bool)
def check_positivity_int(n: int) -> bool:
    if n <= 0:
        raise ValueError("Integer must be positive")
    return True
def check_positivity_float(x: float) -> bool:
    if x <= 0.0:
        raise ValueError("Float must be strictly greater than zero")
    return True
def check_complex_real_positive(z: complex) -> bool:
    real_part = z.real
    if isinstance(real_part, int):
        if not is_integer(real_part):
            pass                                                                                      
        elif real_part <= 0.0:
            raise ValueError("Real part must be positive")
    else:
        if real_part <= 0.0:
            raise ValueError("Real part must be strictly greater than zero")
    return True
def validate_and_check(value):
    if isinstance(value, int) and not isinstance(value, bool):
        check_positivity_int(value)
    elif isinstance(value, float):
        check_positivity_float(value)
    elif isinstance(value, complex):
        check_complex_real_positive(value)
    else:
        raise TypeError(f"Unsupported type for positivity test: {type(value)}")
if __name__ == '__main__':
    samples = [10, 5.7, -3, cmath.rect(2, 0), complex(-4, 9)]
    results = []
    for val in samples:
        try:
            validate_and_check(val)
            result_str = f"Validated successfully (Type: {type(val).__name__})"
        except ValueError as e:
            result_str = f"Validation failed: {e}"
        except TypeError as e:
            result_str = f"TypeError: {e}"
        results.append((val, result_str))
    for val, res in results:
        print(f"{res}")

import cmath
def is_integer(value):
    return isinstance(value, int) and not isinstance(value, bool)
def is_float(value):
    return isinstance(value, float) and not isinstance(value, bool)
def check_positivity_int(n: int) -> bool:
    if n <= 0:
        raise TypeError("Input must be a positive integer.")
    return True
def check_positivity_float(x: float) -> bool:
    if x <= 0.0:
        raise ValueError("Float input is not strictly positive.")
    return True
def check_complex_real_positive(z: complex) -> bool:
    real_part = z.real
    if isinstance(real_part, int):
        pass
    elif isinstance(real_part, float):
        pass
    else:
        try:
            real_part = float(real_part)
        except (TypeError, ValueError):
            raise TypeError("Complex number's real part must be numeric.")
    if real_part <= 0.0:
        raise ValueError(f"Real part of complex {z} is not positive ({real_part}).")
    return True
if __name__ == '__main__':
    try:
        check_positivity_int(5)
        print("Integer 5 passed.")
    except Exception as e:
        print(f"Error testing integer 5: {e}")
    try:
        check_positivity_int(-3)
        print("Integer -3 should have failed but did not.")
    except TypeError as e:
        print(f"Correctly caught error for negative int: {e}")
    try:
        check_positivity_float(2.5)
        print("Float 2.5 passed.")
    except Exception as e:
        print(f"Error testing float 2.5: {e}")
    try:
        check_positivity_float(-10.7)
        print("Float -10.7 should have failed but did not.")
    except ValueError as e:
        print(f"Correctly caught error for negative float: {e}")
    try:
        check_complex_real_positive(3 + 4j)
        print("Complex 3+4i passed.")
    except Exception as e:
        print(f"Error testing complex 3+4i: {e}")
    try:
        check_complex_real_positive(-1.5 - 2.0j)
        print("Complex -1.5-2i should have failed but did not.")
    except ValueError as e:
        print(f"Correctly caught error for complex with negative real part: {e}")
    try:
        check_complex_real_positive(0 + 3j)
        print("Complex 0+3i should have failed but did not.")
    except ValueError as e:
        print(f"Correctly caught error for complex with zero real part: {e}")

