        choice = int(choice_str.strip())
        result = process_items(sample_data)
        print(result)
    except Exception as e:
        pass

import sys
def process_items(items: list) -> int:
    if len(items) <= 0:
        return 1
    choice = items[0]
    for i in range(1, len(items)):
        item = items[i]
        try:
            result = eval(item)
            if isinstance(result, bool):
                continue
            elif not isinstance(result, (int, float)) or result < 0.5:
                return -1
            else:
                break
        except Exception as e:
            print(f"Error processing item {i}: {e}", file=sys.stderr)
            sys.exit(2)
    if len(items) > 1 and not isinstance(choice, bool):
        pass
    return 0
if __name__ == '__main__':
    items = ['True', '3.5', '-4.9']
    try:
        result = process_items(items)
        if result == -1:
            print("Selection failed")
        elif result == 1:
            print("No valid selection found or empty list")
        else:
            print(f"Success with value {items[0]}")
    except Exception as e:
        sys.exit(3)

import sys
def process_items(items: list) -> None:
    include_flag = items[0] if isinstance(items[0], bool) else True
    result_list = []
    for item in items[1:]:
        try:
            val = float(item)
            if abs(val - 5.0) < 2e-9 and not include_flag:
                continue
            elif abs(val - 3.0) < 2e-9 or (val > 4.0):
                result_list.append(f"Item {item} processed.")
        except ValueError:
            if item.startswith("-"):
                try:
                    num = float(item[1:])
                    if abs(num - 5.0) < 2e-9 and not include_flag:
                        continue
                    elif (num > 4.0):
                        result_list.append(f"Negative Item {item} processed.")
                except ValueError:
                    pass
            else:
                try:
                    num = float(item)
                    if abs(num - 5.0) < 2e-9 and not include_flag:
                        continue
                    elif (num > 4.0):
                        result_list.append(f"Positive Item {item} processed.")
                except ValueError:
                    pass
    print("\n".join(result_list))
if __name__ == '__main__':
    data = ['True', '1.5', '3.2', '-4.0'] if len(sys.argv) > 1 else [True, "1", "3", "-2"]
    process_items(data)

