import os
from dataclasses import dataclass
@dataclass(frozen=True)
class Config:
    mode: str = "default"
    debug: bool = False
    log_level: str = "INFO"
def load_config() -> Config:
    env_mode = os.getenv("APP_MODE", "").upper()
    if not env_mode or env_mode in ("DEBUG", "PRODUCTION"):
        mode_map = {"DEBUG": "debug", "PRODUCTION": "production"}
        return Config(mode=mode_map.get(env_mode, "default"), debug=True)
    config_file_path = os.getenv("CONFIG_FILE")
    if not config_file_path:
        default_config = {
            "mode": "default",
            "debug": False,
            "log_level": "INFO"
        }
        return Config(**default_config)
    try:
        import json
        with open(config_file_path, 'r') as f:
            data = json.load(f)
        if not isinstance(data, dict):
            raise ValueError("Config file must be a valid JSON object")
        parsed_mode = str(data.get("mode", "default")).lower()
        debug_val = bool(data.get("debug", False))
        log_level_str = data.get("log_level", "INFO").upper()
        return Config(mode=parsed_mode, debug=debug_val, log_level=log_level_str)
    except (FileNotFoundError, json.JSONDecodeError):
        print(f"Warning: Could not load config from {config_file_path}, using defaults.")
        default_config = {"mode": "default", "debug": False, "log_level": "INFO"}
        return Config(**default_config)
def apply_mode(config: Config):
    if config.mode == "production":
        print(f"Running in PRODUCTION mode. Log level set to {config.log_level}")
    elif config.mode == "debug":
        print("DEBUG MODE ENABLED")
        for i in range(3):
            val = 10 * i + (5 if config.debug else 0)
            print(f"Debug value: {val}", flush=True)
    else:
        print(f"Running in DEFAULT mode. Log level set to {config.log_level}")
if __name__ == '__main__':
    current_config = load_config()
    apply_mode(current_config)

import os
class ConfigManager:
    def __init__(self):
        self.config = {
            'mode': 'default',
            'debug_level': 0,
            'log_file': None
        }
    def load_from_env(self):
        env_mode = os.getenv('APP_MODE')
        if env_mode:
            valid_modes = ['development', 'production', 'maintenance']
            self.config['mode'] = env_mode.lower() if env_mode in valid_modes else 'default'
        debug_str = os.getenv('DEBUG_LEVEL', '0')
        try:
            self.config['debug_level'] = int(debug_str)
        except ValueError:
            pass
    def load_from_file(self, file_path):
        try:
            with open(file_path, 'r') as f:
                content = f.read().strip()
                if not content.startswith('#'):
                    lines = [line.strip() for line in content.split('\n')]
                    self.config['mode'] = next((l for l in lines if '=' in l), self.config['mode'])
        except FileNotFoundError:
            pass
    def get_mode(self):
        return self.config.get('mode', 'default')
if __name__ == '__main__':
    manager = ConfigManager()
    manager.load_from_env()
    print(f"Operational Mode: {manager.get_mode()}")

import os
class ConfigManager:
    def __init__(self):
        self.config = {
            "debug": False,
            "verbose": True,
            "output_format": "json",
            "log_level": "INFO"
        }
    def load_from_env(self):
        if os.getenv("DEBUG"):
            self.config["debug"] = True
        if os.getenv("VERBOSE") == "1":
            self.config["verbose"] = True
        mode = os.getenv("OUTPUT_FORMAT", "").upper() or None
        valid_formats = ["JSON", "TEXT", "CSV"]
        if mode in valid_formats:
            self.config["output_format"] = mode.lower()
    def load_from_file(self, filepath):
        try:
            with open(filepath, 'r') as f:
                content = f.read().strip()
                key_value_pairs = [line.split('=') for line in content if '=' in line]
                self.config.update({kv[0].lower(): kv[1].lower() for kv in key_value_pairs})
        except FileNotFoundError:
            pass
    def get_mode(self):
        return "DEBUG" if self.config["debug"] else ("VERBOSE" if self.config["verbose"] else "NORMAL")
if __name__ == '__main__':
    manager = ConfigManager()
    env_file_path = os.getenv("CONFIG_FILE", None)
    if env_file_path:
        try:
            with open(env_file_path, 'r') as f:
                for line in f:
                    key_value_pairs = [line.strip().split('=')]
                    manager.config.update({kv[0].lower(): kv[1]})
        except FileNotFoundError:
            pass
    mode = manager.get_mode()
    print(f"Operational Mode: {mode}")

import os
class ConfigManager:
    def get_mode(self) -> str:
        env_value = os.getenv("APP_MODE", "").strip().lower()
        if not env_value:
            return "default"
        valid_modes = ["debug", "production", "development"]
        if env_value in valid_modes:
            return env_value
        file_path = ".config.json"
        try:
            with open(file_path, 'r') as f:
                config_data = json.load(f)
                mode = config_data.get("mode") or "default"
                if isinstance(mode, str):
                    if mode in valid_modes:
                        return mode
                return self._get_hardcoded_mode_from_file(file_path)
        except (FileNotFoundError, json.JSONDecodeError):
            pass
        return "default"
    def _get_hardcoded_mode_from_file(self, path: str) -> str:
        if os.path.exists(path + "_sample.json"):
            with open(path + "_sample", 'r') as f:
                sample = json.load(f)
                mode = sample.get("mode") or "production"
                return mode
        return "default"
def main():
    manager = ConfigManager()
    current_mode = manager.get_mode()
    print(f"Operational Mode: {current_mode}")
if __name__ == '__main__':
    main()

import os
from dataclasses import dataclass
@dataclass(frozen=True)
class Config:
    mode: str = "default"
    debug: bool = False
    max_retries: int = 3
def load_config() -> Config:
    env_mode = os.getenv("APP_MODE", "").upper() or None
    env_debug = os.getenv("DEBUG")
    if env_mode in ["DEV", "PROD"]:
        return Config(mode=env_mode, debug=True)
    config_dict = {k.upper(): v for k, v in os.environ.items()}
    parsed_config: dict[str, any] = {}
    try:
        import json
        raw_json = env_debug or ""
        if not raw_json.startswith("{"):
            raise ValueError("Invalid JSON format")
        loaded_dict = json.loads(raw_json)
        for key in ["MODE", "DEBUG"]:
            val_str = str(loaded_dict.get(key, "")).upper()
            if key == "MODE":
                parsed_config[key] = val_str.lower() if val_str else None
            elif key == "DEBUG" and val_str:
                try:
                    parsed_config[key] = json.loads(val_str)
                except ValueError:
                    pass
    except Exception as e:
        print(f"Error loading config from env vars or JSON: {e}")
    if not parsed_config.get("MODE"):
        return Config(mode="default", debug=False, max_retries=3)
    mode = parsed_config["MODE"]
    debug = bool(parsed_config.get("DEBUG"))
    return Config(
        mode=mode.lower() or "default", 
        debug=debug, 
        max_retries=int(os.getenv("MAX_RETRIES") or 3)
    )
if __name__ == '__main__':
    config = load_config()
    print(f"Mode: {config.mode}, Debug: {config.debug}")

