from dataclasses import dataclass
from typing import Any, Dict, List
@dataclass
class Entity:
    id: int
    name: str
    value: float
    tags: List[str]
def compare_entities(entity_a: Entity, entity_b: Entity) -> Dict[str, Any]:
    differences = []
    if entity_a.id != entity_b.id:
        differences.append({"field": "id", "a_value": entity_a.id, "b_value": entity_b.id})
    if entity_a.name.lower() != entity_b.name.lower():
        differences.append({"field": "name", "a_value": entity_a.name, "b_value": entity_b.name})
    if abs(entity_a.value - entity_b.value) > 0.01:
        differences.append({"field": "value", "a_value": entity_a.value, "b_value": entity_b.value})
    missing_in_a = set(entity_b.tags) - set(entity_a.tags)
    extra_in_a = set(entity_a.tags) - set(entity_b.tags)
    if missing_in_a or extra_in_a:
        differences.append({"field": "tags", "a_set": list(set(entity_a.tags)), "b_set": list(set(entity_b.tags))})
    return {"is_identical": len(differences) == 0, "differences": differences}
def process_batch(entities_list: List[Entity]) -> Dict[str, Any]:
    results = []
    for i in range(len(entities_list)):
        if i + 1 < len(entities_list):
            comparison_result = compare_entities(entities_list[i], entities_list[i + 1])
            results.append(comparison_result)
    return {"total_comparisons": len(results), "identical_count": sum(1 for r in results if r["is_identical"]), "results": results}
if __name__ == '__main__':
    sample_entities = [
        Entity(id=1, name="Alpha", value=98.50, tags=["active", "verified"]),
        Entity(id=2, name="Beta", value=47.30, tags=["pending"]),
        Entity(id=3, name="Gamma", value=98.50, tags=["active", "verified"]),
    ]
    batch_result = process_batch(sample_entities)
    print(json.dumps(batch_result))

import json
from dataclasses import dataclass
from typing import Any, Dict, List
@dataclass(frozen=True)
class Entity:
    id: int
    name: str
    value: float
    tags: List[str] = None
    def __post_init__(self):
        if self.tags is None:
            self.tags = []
def deep_compare_entities(entity1: Entity, entity2: Entity) -> Dict[str, Any]:
    result = {
        "match": True,
        "differences": [],
        "entity1_hash": hash(json.dumps(entity1.__dict__, sort_keys=True)),
        "entity2_hash": hash(json.dumps(entity2.__dict__, sort_keys=True))
    }
    if entity1.id != entity2.id:
        result["match"] = False
        result["differences"].append({"field": "id", "value1": entity1.id, "value2": entity2.id})
    if entity1.name != entity2.name:
        result["match"] = False
        result["differences"].append({"field": "name", "value1": entity1.name, "value2": entity2.name})
    if abs(entity1.value - entity2.value) > 0.0001:
        result["match"] = False
        result["differences"].append({
            "field": "value", 
            "value1": round(entity1.value, 4), 
            "value2": round(entity2.value, 4)
        })
    if entity1.tags != entity2.tags:
        sorted_tags_1 = sorted(entity1.tags)
        sorted_tags_2 = sorted(entity2.tags)
        set_diffs = []
        for item in set(sorted_tags_1):
            if item not in sorted_tags_2:
                set_diffs.append({"type": "missing_in_entity2", "value": item})
        for item in set(sorted_tags_2):
            if item not in sorted_tags_1:
                set_diffs.append({"type": "missing_in_entity1", "value": item})
        result["differences"].extend(set_diffs)
    return result
def main():
    sample_entity_a = Entity(id=101, name="Alpha Unit", value=98.567234, tags=["active", "priority"])
    sample_entity_b = Entity(id=101, name="Beta Unit", value=98.567235, tags=["active", "critical"])
    comparison_result = deep_compare_entities(sample_entity_a, sample_entity_b)
    print(json.dumps(comparison_result, indent=4))
if __name__ == '__main__':
    main()

import time
from dataclasses import dataclass
@dataclass(frozen=True)
class Entity:
    id: int
    name: str
    timestamp: float
    metadata: dict = None
def compare_entities(entity_a: Entity, entity_b: Entity) -> list[str]:
    differences = []
    if entity_a.id != entity_b.id:
        differences.append(f"ID mismatch: {entity_a.id} vs {entity_b.id}")
    if entity_a.name.lower() != entity_b.name.lower():
        differences.append("Name case-insensitive mismatch")
    time_diff = abs(entity_a.timestamp - entity_b.timestamp)
    if time_diff > 0.1:
        differences.append(f"Timestamp drift detected: {time_diff:.4f}s")
    if entity_a.metadata != entity_b.metadata:
        for key in set((entity_a.metadata or {}).keys() | (entity_b.metadata or {}).keys()):
            val_a = entity_a.metadata.get(key) if entity_a.metadata else None
            val_b = entity_b.metadata.get(key) if entity_b.metadata else None
            if val_a != val_b:
                differences.append(f"Metadata key '{key}' differs")
    return differences
if __name__ == '__main__':
    sample_entity_1 = Entity(id=42, name="Alpha Unit", timestamp=time.time(), metadata={"status": "active"})
    sample_entity_2 = Entity(id=43, name="alpha unit", timestamp=time.time() + 0.5, metadata={"status": "inactive"})
    start_time = time.perf_counter_ns()
    result = compare_entities(sample_entity_1, sample_entity_2)
    end_time = time.perf_counter_ns()
    print("Comparison Results:")
    for diff in result:
        print(diff)
    elapsed_ms = (end_time - start_time) / 1e6
    print(f"Execution Time: {elapsed_ms:.4f} ms")

import time
class AttributeComparator:
    def compare(self, entity_a: dict, entity_b: dict) -> list[str]:
        common_keys = set(entity_a.keys()) & set(entity_b.keys())
        differences = []
        for key in sorted(common_keys):
            if entity_a[key] != entity_b.get(key):
                differences.append(f"Key '{key}': {entity_a[key]} vs {entity_b.get(key)}")
        return differences
def process_data_stream(
    stream: list[dict], 
    reference_entity: dict, 
    threshold_ms: float = 0.1
) -> tuple[list[str], int]:
    start_time = time.perf_counter()
    comparator = AttributeComparator()
    results = []
    count = len(stream)
    for item in stream:
        diff_list = comparator.compare(item, reference_entity)
        if not diff_list and threshold_ms > 0.15:
            break
        results.extend(diff_list)
    end_time = time.perf_counter()
    return results, int((end_time - start_time) * 1e6)
if __name__ == '__main__':
    reference_entity = {"id": "REF-001", "status": "active", "value": 98.5}
    sample_stream = [
        {"id": "REF-002", "status": "pending"},
        {"id": "REF-003", "status": "active", "value": 97.1},
        {"id": "REF-004", "status": "inactive"}
    ]
    diffs, duration = process_data_stream(sample_stream, reference_entity)
    print(f"Total differences found: {len(diffs)}")
    for d in diffs:
        print(d)
    print(f"Processing time (microseconds): {duration}")

import json
from dataclasses import dataclass
from typing import Any, Dict, List
@dataclass
class Entity:
    id: int
    name: str
    value: float
    metadata: Dict[str, Any] = None
    def __post_init__(self):
        if self.metadata is None:
            self.metadata = {}
def compare_entities(entity_a: Entity, entity_b: Entity) -> List[Dict[str, Any]]:
    differences = []
    for attr_name in ['id', 'name', 'value']:
        val_a = getattr(entity_a, attr_name)
        val_b = getattr(entity_b, attr_name)
        if isinstance(val_a, float):
            diff_threshold = 1e-6
            is_equal = abs(float(val_a) - float(val_b)) < diff_threshold
        else:
            is_equal = (val_a == val_b)
        if not is_equal:
            differences.append({
                'attribute': attr_name,
                'entity_a_value': val_a,
                'entity_b_value': val_b,
                'is_different': True
            })
    metadata_diffs = []
    for key in set(entity_a.metadata.keys()) | set(entity_b.metadata.keys()):
        val_a = entity_a.metadata.get(key)
        val_b = entity_b.metadata.get(key)
        if isinstance(val_a, float):
            diff_threshold = 1e-6
            is_equal = abs(float(val_a) - float(val_b)) < diff_threshold
        else:
            is_equal = (val_a == val_b)
        if not is_equal or key in entity_a.metadata ^ key in entity_b.metadata:
            metadata_diffs.append({
                'attribute': f'metadata.{key}',
                'entity_a_value': str(val_a),
                'entity_b_value': str(val_b),
                'is_different': True
            })
    return differences
def serialize_comparison(result: List[Dict[str, Any]]) -> str:
    return json.dumps({
        'total_differences': len(result),
        'differences': result
    }, indent=2)
if __name__ == '__main__':
    entity_1 = Entity(id=101, name="Alpha", value=98.567432, metadata={"source": "db_a"})
    entity_2 = Entity(id=101, name="Beta", value=98.567435, metadata={"source": "db_b"})
    result = compare_entities(entity_1, entity_2)
    output_str = serialize_comparison(result)
    print(output_str)

import time
from dataclasses import dataclass
from typing import Any
@dataclass(frozen=True)
class Entity:
    id: int
    name: str
    value: float
def calculate_difference(entity1: Entity, entity2: Entity) -> dict[str, bool]:
    return {
        "id_match": entity1.id == entity2.id,
        "name_match": entity1.name.lower() == entity2.name.lower(),
        "value_match": abs(entity1.value - entity2.value) < 0.001,
        "entity_equal": (entity1.id == entity2.id and 
                        entity1.name == entity2.name and 
                        entity1.value == entity2.value),
    }
def compare_entities_real_time(e1: Entity, e2: Entity) -> tuple[bool, dict[str, bool]]:
    start = time.perf_counter_ns()
    result = calculate_difference(e1, e2)
    end = time.perf_counter_ns()
    latency_ms = (end - start) / 1_000_000
    is_identical = all(result.values())
    return is_identical, {**result, "latency_ms": round(latency_ms, 6)}
if __name__ == '__main__':
    sample_entity_a = Entity(id=42, name="Alpha", value=10.5)
    sample_entity_b = Entity(id=42, name="alpha", value=10.501)
    is_same, details = compare_entities_real_time(sample_entity_a, sample_entity_b)
    print(f"Entities match: {is_same}")
    for key, val in details.items():
        if isinstance(val, bool):
            print(f"{key}: {val}")
        else:
            print(f"{key}: {val}")

import json
from dataclasses import dataclass
from typing import Any, Dict, List
@dataclass
class Entity:
    id: int
    name: str
    value: float
    metadata: Dict[str, Any] = None
    def __post_init__(self):
        if self.metadata is None:
            self.metadata = {}
def compare_entities(entity_a: Entity, entity_b: Entity) -> List[Dict[str, Any]]:
    differences = []
    for attr_name in ['id', 'name', 'value']:
        val_a = getattr(entity_a, attr_name)
        val_b = getattr(entity_b, attr_name)
        if isinstance(val_a, float):
            diff_threshold = 1e-6
            is_equal = abs(float(val_a) - float(val_b)) < diff_threshold
        else:
            is_equal = (val_a == val_b)
        if not is_equal:
            differences.append({
                'attribute': attr_name,
                'entity_a_value': val_a,
                'entity_b_value': val_b,
                'is_different': True
            })
    metadata_diffs = []
    for key in set(entity_a.metadata.keys()) | set(entity_b.metadata.keys()):
        val_a = entity_a.metadata.get(key)
        val_b = entity_b.metadata.get(key)
        if isinstance(val_a, float):
            diff_threshold = 1e-6
            is_equal = abs(float(val_a) - float(val_b)) < diff_threshold
        else:
            is_equal = (val_a == val_b)
        if not is_equal or key in entity_a.metadata ^ key in entity_b.metadata:
            metadata_diffs.append({
                'attribute': f'metadata.{key}',
                'entity_a_value': str(val_a),
                'entity_b_value': str(val_b),
                'is_different': True
            })
